#include "unity.h"
#include "mock_motor_platform.h"
#include "mock_safety_platform.h"
#include "app.h"
#include "app_config.h"
#include "logger.h"
#include "motor_platform.h"
#include "motor_sequence.h"
#include "safety_platform.h"
#include "sine_control.h"

static int delay_calls;
static int enable_delay_call;

static void delay_callback(uint32_t milliseconds, int cmock_num_calls)
{
    (void)milliseconds;
    (void)cmock_num_calls;
    delay_calls++;
}

static x_nucleo_ihm16m1_status_t enable_callback(bool enable, int cmock_num_calls)
{
    (void)cmock_num_calls;
    if (enable) {
        enable_delay_call = delay_calls;
    }
    return X_NUCLEO_IHM16M1_OK;
}

static x_nucleo_ihm16m1_status_t check_fault_callback(bool *fault,
                                                       int cmock_num_calls)
{
    (void)cmock_num_calls;
    if (fault != NULL) {
        *fault = false;
    }
    return X_NUCLEO_IHM16M1_OK;
}

static void configure_successful_automatic_run(void)
{
    motor_platform_led_on_Ignore();
    motor_platform_init_IgnoreAndReturn(X_NUCLEO_IHM16M1_OK);
    motor_platform_delay_ms_StubWithCallback(delay_callback);
    motor_platform_enable_StubWithCallback(enable_callback);
    motor_platform_drive_IgnoreAndReturn(X_NUCLEO_IHM16M1_OK);

    safety_platform_init_IgnoreAndReturn(X_NUCLEO_IHM16M1_OK);
    safety_platform_check_fault_StubWithCallback(check_fault_callback);
    safety_platform_disable_IgnoreAndReturn(X_NUCLEO_IHM16M1_OK);
    safety_platform_watchdog_refresh_Ignore();
}

static void run_automatic_sequence(int *recorded_delays,
                                   int *recorded_enable_delay)
{
    delay_calls = 0;
    enable_delay_call = -1;
    app_start();
    *recorded_delays = delay_calls;
    *recorded_enable_delay = enable_delay_call;
}

void setUp(void)
{
    delay_calls = 0;
    enable_delay_call = -1;
}

void tearDown(void)
{
}

void test_NFR_014_01(void)
{
    configure_successful_automatic_run();

    app_start();

    /* The application reaches enable only after the 3-second boot delay. */
    TEST_ASSERT_EQUAL_INT(APP_MOTOR_START_DELAY_MS / APP_MOTOR_CONTROL_PERIOD_MS,
                          enable_delay_call);
    /* The automatic sequence runs through its complete 20-second timeline. */
    TEST_ASSERT_EQUAL_INT(20000 / APP_MOTOR_CONTROL_PERIOD_MS, delay_calls);
}

void test_NFR_014_02(void)
{
    int first_run_delays;
    int first_run_enable_delay;
    int second_run_delays;
    int second_run_enable_delay;

    configure_successful_automatic_run();

    /* A run with no UART input. */
    run_automatic_sequence(&first_run_delays, &first_run_enable_delay);

    /* A second run represents arbitrary external input; app_start has no UART
       interface, so the same automatic path is exercised unchanged. */
    run_automatic_sequence(&second_run_delays, &second_run_enable_delay);

    TEST_ASSERT_EQUAL_INT(first_run_enable_delay, second_run_enable_delay);
    TEST_ASSERT_EQUAL_INT(first_run_delays, second_run_delays);
    TEST_ASSERT_EQUAL_INT(APP_MOTOR_START_DELAY_MS / APP_MOTOR_CONTROL_PERIOD_MS,
                          first_run_enable_delay);
    TEST_ASSERT_EQUAL_INT(20000 / APP_MOTOR_CONTROL_PERIOD_MS, first_run_delays);
}
